                    paymentTypeOptions: scope.product.paymentTypeOptions.length > 0 ? scope.product.paymentTypeOptions : [],
                    assetAccountOptions: scope.assetLiabilityAccountOptions.length > 0 ? scope.assetLiabilityAccountOptions : []
